CREATE TABLE IF NOT EXISTS public.payroll_shifts (id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.payroll_employees(id) on delete cascade,shift_date date not null,start_time time,end_time time,hours_worked numeric not null default 0,overtime_hours numeric not null default 0,status text not null default 'completed',notes text,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.payroll_deductions (id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.payroll_employees(id) on delete cascade,amount numeric not null, deduction_date date not null default current_date,kind text not null default 'other',reference text,notes text,status text not null default 'open',created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.payroll_statutory_config (id uuid primary key default gen_random_uuid(),restaurant_id uuid not null unique references public.restaurants(id) on delete cascade,pf_enabled boolean not null default false,esi_enabled boolean not null default false,pt_enabled boolean not null default false,tds_enabled boolean not null default false,pf_employee_rate numeric not null default 0,esi_employee_rate numeric not null default 0,pt_fixed numeric not null default 0,tds_rate numeric not null default 0,metadata jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.payroll_ledger (id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,payroll_run_id uuid references public.payroll_runs(id) on delete set null,employee_id uuid references public.payroll_employees(id) on delete set null,entry_type text not null,amount numeric not null,reference text,created_at timestamptz not null default now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_payroll_attendance_day ON public.payroll_attendance(restaurant_id,employee_id,attendance_date); CREATE UNIQUE INDEX IF NOT EXISTS uq_payroll_run_period ON public.payroll_runs(restaurant_id,period_start,period_end); CREATE UNIQUE INDEX IF NOT EXISTS uq_payroll_employee_code ON public.payroll_employees(restaurant_id,employee_code) WHERE employee_code IS NOT NULL; CREATE INDEX IF NOT EXISTS idx_payroll_shift_employee_date ON public.payroll_shifts(restaurant_id,employee_id,shift_date); CREATE INDEX IF NOT EXISTS idx_payroll_deduction_employee_date ON public.payroll_deductions(restaurant_id,employee_id,deduction_date); CREATE INDEX IF NOT EXISTS idx_payroll_ledger_run_employee ON public.payroll_ledger(restaurant_id,payroll_run_id,employee_id);
ALTER TABLE public.payroll_shifts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_deductions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_statutory_config ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_ledger ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS payroll_shift_member ON public.payroll_shifts; CREATE POLICY payroll_shift_member ON public.payroll_shifts FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_deduction_member ON public.payroll_deductions; CREATE POLICY payroll_deduction_member ON public.payroll_deductions FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_statutory_member ON public.payroll_statutory_config; CREATE POLICY payroll_statutory_member ON public.payroll_statutory_config FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_ledger_member ON public.payroll_ledger; CREATE POLICY payroll_ledger_member ON public.payroll_ledger FOR SELECT USING(is_super_admin() OR is_restaurant_member(restaurant_id));
ALTER TABLE public.payroll_employees ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_salary_structures ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_attendance ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_advances ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payroll_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS payroll_employee_member ON public.payroll_employees; CREATE POLICY payroll_employee_member ON public.payroll_employees FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_salary_member ON public.payroll_salary_structures; CREATE POLICY payroll_salary_member ON public.payroll_salary_structures FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_attendance_member ON public.payroll_attendance; CREATE POLICY payroll_attendance_member ON public.payroll_attendance FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_advance_member ON public.payroll_advances; CREATE POLICY payroll_advance_member ON public.payroll_advances FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_run_member ON public.payroll_runs; CREATE POLICY payroll_run_member ON public.payroll_runs FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id)); DROP POLICY IF EXISTS payroll_item_member ON public.payroll_items; CREATE POLICY payroll_item_member ON public.payroll_items FOR ALL USING(is_super_admin() OR is_restaurant_member(restaurant_id)) WITH CHECK(is_super_admin() OR is_restaurant_member(restaurant_id));
CREATE OR REPLACE FUNCTION public.p1_2_process_payroll(p_restaurant_id uuid,p_period_start date,p_period_end date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r payroll_runs%rowtype;e record;s record;days_present numeric;days_absent numeric;paid_leave numeric;hrs numeric;ot numeric;basic numeric;allow numeric;otp numeric;bonus numeric;adv numeric;other numeric;gross numeric;net numeric;pf numeric:=0;esi numeric:=0;pt numeric:=0;tds numeric:=0;count_items int:=0;BEGIN IF NOT(auth.role()='service_role' OR is_super_admin() OR is_restaurant_member(p_restaurant_id)) THEN RAISE EXCEPTION 'Restaurant access denied';END IF;IF p_period_end<p_period_start THEN RAISE EXCEPTION 'Invalid payroll period';END IF;INSERT INTO payroll_runs(restaurant_id,period_start,period_end,status,created_by,processed_at) VALUES(p_restaurant_id,p_period_start,p_period_end,'processed',auth.uid(),now()) ON CONFLICT(restaurant_id,period_start,period_end) DO UPDATE SET status=CASE WHEN payroll_runs.status IN('approved','paid') THEN payroll_runs.status ELSE 'processed' END,processed_at=now() RETURNING * INTO r;IF r.status IN('approved','paid') THEN RETURN jsonb_build_object('success',true,'locked',true,'payroll_run_id',r.id);END IF;DELETE FROM payroll_items WHERE payroll_run_id=r.id;DELETE FROM payroll_ledger WHERE payroll_run_id=r.id;FOR e IN SELECT * FROM payroll_employees WHERE restaurant_id=p_restaurant_id AND active LOOP SELECT * INTO s FROM payroll_salary_structures WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND effective_from<=p_period_end ORDER BY effective_from DESC LIMIT 1;IF NOT FOUND THEN CONTINUE;END IF;SELECT coalesce(sum((status='present')::int),0),coalesce(sum((status='absent')::int),0),coalesce(sum((status='leave')::int),0),coalesce(sum(hours_worked),0),coalesce(sum(overtime_hours),0) INTO days_present,days_absent,paid_leave,hrs,ot FROM payroll_attendance WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND attendance_date BETWEEN p_period_start AND p_period_end;SELECT coalesce(sum(amount),0) INTO adv FROM payroll_advances WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND status='open' AND advance_date<=p_period_end;SELECT coalesce(sum(amount),0) INTO other FROM payroll_deductions WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND status='open' AND deduction_date<=p_period_end;other:=other+coalesce(s.deductions_fixed,0);basic:=round(s.basic_salary*greatest(days_present+paid_leave,0)/greatest((p_period_end-p_period_start+1),1),2);allow:=round(s.allowances*greatest(days_present+paid_leave,0)/greatest((p_period_end-p_period_start+1),1),2);otp:=round(ot*s.overtime_rate,2);bonus:=round(s.bonus_rate,2);gross:=basic+allow+otp+bonus;SELECT CASE WHEN pf_enabled THEN gross*pf_employee_rate/100 ELSE 0 END,CASE WHEN esi_enabled THEN gross*esi_employee_rate/100 ELSE 0 END,CASE WHEN pt_enabled THEN pt_fixed ELSE 0 END,CASE WHEN tds_enabled THEN gross*tds_rate/100 ELSE 0 END INTO pf,esi,pt,tds FROM payroll_statutory_config WHERE restaurant_id=p_restaurant_id;net:=greatest(gross-adv-other-pf-esi-pt-tds,0);INSERT INTO payroll_items(restaurant_id,payroll_run_id,employee_id,days_present,days_absent,paid_leave,hours_worked,overtime_hours,basic_earned,allowances,overtime_pay,bonus,advance_deduction,other_deductions,gross_pay,net_pay,metadata) VALUES(p_restaurant_id,r.id,e.id,days_present,days_absent,paid_leave,hrs,ot,basic,allow,otp,bonus,adv,other+pf+esi+pt+tds,gross,net,jsonb_build_object('pf',pf,'esi',esi,'pt',pt,'tds',tds));INSERT INTO payroll_ledger(restaurant_id,payroll_run_id,employee_id,entry_type,amount,reference) VALUES(p_restaurant_id,r.id,e.id,'gross',gross,e.name),(p_restaurant_id,r.id,e.id,'advance',-adv,e.name),(p_restaurant_id,r.id,e.id,'deductions',-(other+pf+esi+pt+tds),e.name),(p_restaurant_id,r.id,e.id,'net',net,e.name);UPDATE payroll_advances SET status='settled' WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND status='open' AND advance_date<=p_period_end;UPDATE payroll_deductions SET status='settled' WHERE restaurant_id=p_restaurant_id AND employee_id=e.id AND status='open' AND deduction_date<=p_period_end;count_items:=count_items+1;END LOOP;RETURN jsonb_build_object('success',true,'payroll_run_id',r.id,'items',count_items);END $$;
